import { useState } from "react";

function ChonMon() {
  const [mon, setMon] = useState("Toan");
  return (
    <div>
      <select value={mon} onChange={(e) => setMon(e.target.value)}>
        <option>Toan</option>
        <option>Ly</option>
        <option>Hoa</option>
      </select>
      <p>Da chon: {mon}</p>
    </div>
  );
}

export default ChonMon;
